"use strict";
import { InterfacePageName } from "@uniswap/analytics-events";
import { LiquidityTokenSortMethod, sortAscendingAtom, sortMethodAtom } from "components/Tokens/state";
import { useUpdateAtom } from "jotai/utils";
import { useEffect } from "react";
import { ExploreContextProvider } from "state/explore";
import { Flex } from "ui/src";
import Trace from "uniswap/src/features/telemetry/Trace";
import { useEnabledChains } from "uniswap/src/features/chains/hooks/useEnabledChains";
import LiquidityPoolVoting from "./components/LiquidityPool";
import { LiquidityPoolsTable } from "./components/LiquidityPoolsTable";
import LiquidityPositions from "./components/LiquidityPositions";
import LiquidiProvider from "./components/LiquidityProvider";
import { FilterProvider } from "./contexts/FilterContext";
export default function DepositLiquidity() {
  const { defaultChainId } = useEnabledChains();
  const setSortMethod = useUpdateAtom(sortMethodAtom);
  const setSortAscending = useUpdateAtom(sortAscendingAtom);
  useEffect(() => {
    setSortMethod(LiquidityTokenSortMethod.APR);
    setSortAscending(false);
  }, [setSortMethod, setSortAscending]);
  return <FilterProvider>
      <Flex
    mt="$spacing24"
    width="100%"
    px="$spacing40"
    maxWidth={1200}
    pb={"$spacing40"}
    $xl={{
      px: "$spacing12",
      mx: "auto"
    }}
  >
        <LiquidiProvider />
        <LiquidityPositions />

        <Flex mt={"$spacing24"}>
          <LiquidityPoolVoting />
        </Flex>

        <Flex mt={"$spacing24"}>
          <Trace logImpression page={InterfacePageName.VOTE_PAGE}>
            <ExploreContextProvider chainId={defaultChainId}>
              <LiquidityPoolsTable />
            </ExploreContextProvider>
          </Trace>
        </Flex>
      </Flex>
    </FilterProvider>;
}
